-- Baseline: schema as it existed before Flyway (previously generated by ddl-auto=update).
-- Existing databases are baselined at V1 and skip this script; it only runs on an empty database.

CREATE TABLE app_user (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at   TIMESTAMP(6),
    created_by   VARCHAR(255),
    modified_at  TIMESTAMP(6),
    modified_by  VARCHAR(255),
    is_activate  BOOLEAN,
    audit_remark VARCHAR(255),
    username     VARCHAR(255) NOT NULL,
    password     VARCHAR(255) NOT NULL,
    CONSTRAINT uk_app_user_username UNIQUE (username)
);

CREATE TABLE user_address (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at   TIMESTAMP(6),
    created_by   VARCHAR(255),
    modified_at  TIMESTAMP(6),
    modified_by  VARCHAR(255),
    is_activate  BOOLEAN,
    audit_remark VARCHAR(255),
    address      VARCHAR(255),
    email        VARCHAR(255),
    facebook     VARCHAR(255),
    phone        VARCHAR(255),
    phone1       VARCHAR(255),
    user_id      BIGINT REFERENCES app_user (id)
);

CREATE TABLE test_employee_email (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at   TIMESTAMP(6),
    created_by   VARCHAR(255),
    modified_at  TIMESTAMP(6),
    modified_by  VARCHAR(255),
    is_activate  BOOLEAN,
    audit_remark VARCHAR(255),
    email        VARCHAR(255) UNIQUE,
    facebook     VARCHAR(255),
    phone        VARCHAR(255),
    phone1       VARCHAR(255)
);

CREATE TABLE test_employee_index_email (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at   TIMESTAMP(6),
    created_by   VARCHAR(255),
    modified_at  TIMESTAMP(6),
    modified_by  VARCHAR(255),
    is_activate  BOOLEAN,
    audit_remark VARCHAR(255),
    email        VARCHAR(255) UNIQUE,
    facebook     VARCHAR(255),
    phone        VARCHAR(255),
    phone1       VARCHAR(255)
);

CREATE INDEX index_email ON test_employee_index_email (email);
CREATE INDEX index_facebook ON test_employee_index_email (facebook);
CREATE INDEX index_phone ON test_employee_index_email (phone);
